import{z as i,x as d,o as a,c as n,q as o,j as l,D as E,d as r,s,S as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"模型卡与数据卡规范","description":"","frontmatter":{"title":"模型卡与数据卡规范","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/eco-model-data-cards.md","filePath":"llm/eco-model-data-cards.md","lastUpdated":1791063341000}'),B={name:"llm/eco-model-data-cards.md"};function c(D,e,m,p,h,_){const A=d("Mermaid");return a(),n("div",null,[e[2]||(e[2]=o('<h1 id="模型卡与数据卡规范" tabindex="-1">模型卡与数据卡规范 <a class="header-anchor" href="#模型卡与数据卡规范" aria-label="Permalink to &quot;模型卡与数据卡规范&quot;">​</a></h1><div class="epigraph"><p>发布物不是权重一个文件，而是权重、元数据、模型卡与数据卡的一组契约；缺一张卡，下游就多一层猜测。</p><footer>—— 据 Mitchell 等的模型卡、Gebru 等的数据表与 Pushkarna 等的数据卡口径整理</footer></div><p><a href="/llm/eco-derivative-merge-license">上一课</a>把衍生链的账记在血缘台账里，但台账只有你自己看得见。发布要让第三方能审计：这份权重从哪来、能干什么、数据是什么口径。模型卡的内容规范——栏目怎么设、分数怎么配协议——<a href="/llm/model-cards">模型卡与报告</a>已经写过；本课站在发布工程一侧，写开放权重发布特有的卡义务：机器可读元数据、数据卡、以及「开放权重」与「开放数据」的证据落差。后课的版本与分支，都要以卡为锚登记。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开放权重发布最常被指着鼻子的问题不是分数低，而是说不清：训练数据是什么、许可字段为什么与条款文本对不上、这个量化变体出自哪个底座 revision。缺口有两层。第一层是机器层：托管平台的元数据字段（<code>license</code>、<code>base_model</code>、<code>tags</code>）被下游的检索器与审计工具批量解析，字段错了比正文错了传得远——正文靠人读，字段直接进管线。第二层是证据层：绝大多数开放权重发布只放权重，训练数据不公开，数据卡就只能写「不可审计」；把「权重公开」说成「全开放」，是证据层级的常见滑坡。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型卡在发布语境下加三栏。<strong>许可一致性栏</strong>：元数据 <code>license</code> 字段必须与许可文本一致——自定义条款写 <code>other</code> 并用 <code>license_name</code> 与 <code>license_link</code> 指向官方文本，正文不得出现与字段冲突的「可随意商用」表述。<strong>血缘栏</strong>：写上一课的台账摘要——底座、revision、适配器、合并配方，让下游能复算合规口径。<strong>变体栏</strong>：每个量化或指令变体单独标注来源与差异，不共用一张卡。数据卡按 Gebru 等的数据表与 Pushkarna 等的数据卡口径列最小栏目：来源与采集方式、许可与授权链、清洗与过滤操作、个人信息处理、已知缺口与偏差。数据未公开时，栏目照列、值写「不可审计」，而不是删栏目——声明边界本身就是信息。<span class="marginnote">初学者容易以为发布页面是「给人看的」，正文写得漂亮就行。实际上企业入库、平台检索、合规扫描这些自动化管线只读元数据字段，根本不读正文——<code>license</code> 字段一旦写错，下游会整批误采信，等到纠正时每一家下游都要单独通知，成本沿传播链成倍放大。</span></p>',7)),(a(),l(t,null,{default:E(()=>[s(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%9D%83%E9%87%8D%E6%96%87%E4%BB%B6%22%5D%20--%3E%20P%5B%22%E5%8F%91%E5%B8%83%E5%8C%85%22%5D%0A%20%20META%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E5%AD%97%E6%AE%B5%EF%BC%9Alicense%20%2F%20base_model%22%5D%20--%3E%20P%0A%20%20MC%5B%22%E6%A8%A1%E5%9E%8B%E5%8D%A1%EF%BC%9A%E7%94%A8%E9%80%94%E3%80%81%E5%8D%8F%E8%AE%AE%E3%80%81%E8%A1%80%E7%BC%98%E3%80%81%E5%8F%98%E4%BD%93%22%5D%20--%3E%20P%0A%20%20DC%5B%22%E6%95%B0%E6%8D%AE%E5%8D%A1%EF%BC%9A%E6%9D%A5%E6%BA%90%E3%80%81%E8%AE%B8%E5%8F%AF%E3%80%81%E6%B8%85%E6%B4%97%E3%80%81%E7%BC%BA%E5%8F%A3%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20AUD%5B%22%E7%AC%AC%E4%B8%89%E6%96%B9%E5%8F%AF%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20P%20-.-%3E%7C%E6%95%B0%E6%8D%AE%E6%9C%AA%E5%85%AC%E5%BC%80%7C%20NA%5B%22%E6%95%B0%E6%8D%AE%E5%8D%A1%E6%A0%87%E6%B3%A8%E4%B8%8D%E5%8F%AF%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>卡之所以是契约，是因为它的读者要做决策：部署者据「用途与非用途」决定接不接，合规团队据许可一致性决定签不签，研究者据数据卡决定能不能比。机器层优先是因为自动化：平台检索、企业入库扫描、审计工具都先读字段再读正文，一个错误的 <code>license: apache-2.0</code> 会被批量采信，纠正成本沿下游指数放大。这也是<a href="/llm/model-cards">模型卡与报告</a>里「更新权重要发新卡」规则的发布版：卡与权重的对应关系靠 revision 锚定，锚没了，卡就成了漂移的营销页。证据层级上，<a href="/llm/olmo-paper">OLMo</a> 连数据、代码与训练日志一起放出，数据卡可以写实；只放权重的发布，卡的诚实写法是明说哪些环节外人无法复核。</p><p><span class="marginnote">发布训练数据时给语料注入 canary 字符串，是数据卡的自证工具：能证明「这份权重见过我的语料」，也能在污染检测里对账，见 Canary 字符串课。</span></p><p>卡是契约，因为不同读者各取所需、各做决策：</p>',4)),(a(),l(t,null,{default:E(()=>[s(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20CARD%5B%22%E4%B8%80%E5%BC%A0%E6%A8%A1%E5%9E%8B%E5%8D%A1%22%5D%20--%3E%20USE%5B%22%E9%83%A8%E7%BD%B2%E8%80%85%E8%AF%BB%E7%94%A8%E9%80%94%E4%B8%8E%E9%9D%9E%E7%94%A8%E9%80%94%E6%A0%8F%22%5D%0A%20%20CARD%20--%3E%20LIC%5B%22%E5%90%88%E8%A7%84%E5%9B%A2%E9%98%9F%E8%AF%BB%E8%AE%B8%E5%8F%AF%E4%B8%80%E8%87%B4%E6%80%A7%E6%A0%8F%22%5D%0A%20%20CARD%20--%3E%20BL%5B%22%E7%A0%94%E7%A9%B6%E8%80%85%E8%AF%BB%E8%A1%80%E7%BC%98%E6%A0%8F%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%8D%A1%22%5D%0A%20%20USE%20--%3E%20D1%5B%22%E5%86%B3%E5%AE%9A%E6%8E%A5%E4%B8%8D%E6%8E%A5%E5%85%A5%E4%BA%A7%E7%BA%BF%22%5D%0A%20%20LIC%20--%3E%20D2%5B%22%E5%86%B3%E5%AE%9A%E7%AD%BE%E4%B8%8D%E7%AD%BE%E5%90%88%E8%A7%84%22%5D%0A%20%20BL%20--%3E%20D3%5B%22%E5%86%B3%E5%AE%9A%E8%83%BD%E5%90%A6%E5%85%AC%E5%B9%B3%E5%AF%B9%E6%AF%94%E5%A4%8D%E7%8E%B0%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<p><span class="marginnote">可以把证据层级想成菜谱的透明度：只放权重，是给你一份成品菜，你只能尝味道；连数据、代码与训练日志一起放，是连菜谱、食材来源和火候记录都给你，你能重做这道菜、验证每一步。「能品尝」与「能复做」是两个等级的证据——「开放权重」与「全开放」的落差正在这里。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>卡不替代法律审查：许可一致性栏保证的是「卡与条款不打架」，条款本身适不适合你的场景，仍走<a href="/llm/eco-weight-license-terms">条款细读</a>那五段。数据卡在数据不公开时天然只能到「声明的边界」，读者要把它当自述而非证据。<span class="marginnote">「不可审计」不是说「没做检查」，而是说「这一步外人无法复核」。数据不公开时，清洗规则、个人信息处理这些环节第三方只能听发布方自述。如实写出来反而加分：读者能精确区分哪些话是承诺、哪些话是证据，比一栏含糊的「数据经过严格清洗」可信得多。</span>变体多、血缘深时卡会变长，压缩的正确方向是结构化元数据加链接台账，不是删栏目。最后，卡是发布方写的，可信度最终由下一课的社区基准与复算决定——卡承诺的数字，要经得起第三方按协议重跑。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发布包四件：权重、机器可读元数据、模型卡、数据卡；元数据字段被下游管线批量解析，错了比正文传得远。</li><li><code>license</code> 字段与条款文本必须一致，自定义条款走 <code>other</code> 加名称与链接。</li><li>模型卡加血缘栏与变体栏，承接上一课台账；卡随 revision 锚定，更新权重即发新卡。</li><li>数据卡按来源、许可、清洗、缺口列栏目；数据未公开就写「不可审计」，不删栏目。</li><li>开放权重不等于开放数据；全开放要连数据与代码一起放，证据层级才有质变。</li><li>出处：Mitchell 等 2019（模型卡）；Gebru 等 2021（数据表）；Pushkarna 等 2022（数据卡）；OLMo 发布物，按本课程整理。</li></ul>',5))])}const f=i(B,[["render",c]]);export{u as __pageData,f as default};
